);
    always@(posedge clk or negedge rstn)begin
        if(~rstn)begin
            top_ctrl_force_mode_switch_wp                            <=  1'h0;
        end
        else begin
            if(top_ctrl_force_mode_switch_wp==1'h1)begin
                top_ctrl_force_mode_switch_wp                        <=  1'h0;
            end
            else if(reg_wr && reg_addr== 'h0   ) begin
                if (reg_wdata[3]==1'h1)begin
                    top_ctrl_force_mode_switch_wp                        <= 1'h1;
                end
            end
        end
    end
    always@(posedge clk or negedge rstn)begin
        if(~rstn)begin
            int_clear_clear_wp                                       <=  1'h0;
            int_clear_clear_wd                                       <=  7'h0;
        end
        else begin
            if(int_clear_clear_wp==1'h1)begin
                int_clear_clear_wp                                   <=  1'h0;
                int_clear_clear_wd                                   <=  7'h0;
            end
            else if(reg_wr && reg_addr== 'h18  ) begin
                int_clear_clear_wp                                   <= 1'h1;
                int_clear_clear_wd                                   <= reg_wdata[6:0];
            end
        end
    end
    always@(posedge clk or negedge rstn)begin
        if(~rstn)begin
            cdc_fifo_rst_fifo_rst_wp                                 <=  1'h0;
        end
        else begin
            if(cdc_fifo_rst_fifo_rst_wp==1'h1)begin
                cdc_fifo_rst_fifo_rst_wp                             <=  1'h0;
            end
            else if(reg_wr && reg_addr== 'h28  ) begin
                if (reg_wdata[0]==1'h1)begin
                    cdc_fifo_rst_fifo_rst_wp                             <= 1'h1;
                end
            end
        end
    end
    always@(posedge clk or negedge rstn)begin
        if(~rstn)begin
            debug_cfg_seed_load_rx_wp                                <=  1'h0;
        end
        else begin
            if(debug_cfg_seed_load_rx_wp==1'h1)begin
                debug_cfg_seed_load_rx_wp                            <=  1'h0;
